function mailtoParts(href){const q=href.indexOf('?');const email=(q<0?href.slice(7):href.slice(7,q));const params=new URLSearchParams(q<0?'':href.slice(q+1));return{email,subject:params.get('subject')||'',body:params.get('body')||''};}
