async function newPage(browser,w,h){const page=await browser.newPage();await page.setViewport({width:w,height:h,deviceScaleFactor:1});const consoleErrors=[];const pageErrors=[];const requestFailures=[];page.on('console',m=>{if(m.type()==='error')consoleErrors.push(m.text())});page.on('pageerror',e=>pageErrors.push(String(e)));page.on('requestfailed',r=>requestFailures.push({url:r.url(),error:r.failure()?.errorText||''}));return{page,consoleErrors,pageErrors,requestFailures};}
async function goto(page,route){const res=await page.goto(BASE+route,{waitUntil:'networkidle0',timeout:30000});const status=res?.status()||0;return status;}
async function duplicateIds(page){return page.evaluate(()=>{const ids=[...document.querySelectorAll('[id]')].map(x=>x.id);return [...new Set(ids.filter((id,i)=>ids.indexOf(id)!==i))];});}
async function geometry(page){return page.evaluate(()=>({innerWidth:innerWidth,scrollWidth:document.documentElement.scrollWidth,scrollHeight:document.documentElement.scrollHeight}));}
async function fillValues(page,v){await page.evaluate(v=>{const map={product:'rfq-product',grade:'rfq-grade',quantity:'rfq-quantity',destination:'rfq-destination',timing:'rfq-timing',specification:'rfq-specification',contactName:'rfq-contact-name',company:'rfq-company',email:'rfq-email',phone:'rfq-phone',notes:'rfq-notes'};for(const [k,id] of Object.entries(map)){const el=document.getElementById(id);el.value=v[k]||'';el.dispatchEvent(new Event('input',{bubbles:true}));}},v);await new Promise(r=>setTimeout(r,30));}
async function readMailto(page){const href=await page.$eval('#rfq-email-action',a=>a.getAttribute('href'));return mailtoParts(href);}

