 report.summary={salesCases:report.salesCases.length,interactionCases:report.interactionCases.length,mobileInteractions:report.mobileInteractions.length,routingRecords:report.routing.length,phase10Cases:report.phase10.length,phase09Records:report.phase09.length,smokeCases:report.smoke.length,failures:failures.length};
